                    0 <= nr < rows and 0 <= nc < cols and 
                    grid[nr][nc] == 2
                    for nr, nc in neighbors
                )
                if neighbor_has_1:
                    result[r][c] = 1
                elif neighbor_has_2:
                    result[r][c] = 1
