def simple_rule(grid, orientation="col"):  # orientation not used here, keep for potential generalization
    rows = len(grid)
    cols = len(grid[0])
    new_grid = [row[:] for row in grid]

    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 3:
                # Check all 4-connected neighbors
                neighbors = [(r-1, c), (r+1, c), (r, c-1), (r, c+1)]
                is_adjacent_to_2 = False
                for nr, nc in neighbors:
                    if 0 <= nr < rows and 0 <= nc < cols:
