from collections import deque

def bfs_propagation(grid):
    rows = len(grid)
    cols = len(grid[0])
    result = [row[:] for row in grid]

    # Find all cells adjacent to 2 (layer 1)
    q = deque()
    visited = set()
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 2:
                for nr, nc in [(r-1, c), (r+1, c), (r, c-1), (r, c+1)]:
                    if 0 <= nr < rows and 0 <= nc < cols:
                        if result[nr][nc] == 3:
                            result[nr][nc] = 1  # Mark as 1
                            q.append((nr, nc))
                            visited.add((nr, nc))

    # Propagate: cells adjacent to 1 become 1
    while q:
        r, c = q.popleft()
        for nr, nc in [(r-1, c), (r+1, c), (r, c-1), (r, c+1)]:
            if 0 <= nr < rows and 0 <= nc < cols:
                if result[nr][nc] == 3:
                    result[nr][nc] = 1
                    q.append((nr, nc))
                    visited.add((nr, nc))

    return result

