from collections import deque

def analyze_2s_and_paths(grid):
    rows = len(grid)
    cols = len(grid[0])

    # For each 2, do BFS through 3s and track shortest distance
    reachable_from_2 = [[None]*cols for _ in range(rows)]

    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 2:
                # BFS from this 2 through 3s only
                q = deque([(r, c, 0)])
                visited = {(r, c)}
                directions_found = set()

                while q:
                    curr_r, curr_c, d = q.popleft()

                    # Check all 4 directions first
                    directions_found.add((curr_r - d, curr_c - d))  # diagonal for comparison

                    for nr, nc in [(curr_r-1, curr_c), (curr_r+1, curr_c), 
                                  (curr_r, curr_c-1), (curr_r, curr_c+1)]:
                        if 0 <= nr < rows and 0 <= nc < cols:
                            if grid[nr][nc] == 3:
                                if (nr, nc) not in visited:
                                    visited.add((nr, nc))
                                new_d = d + 1
                                if reachable_from_2[nr][nc] is None or new_d < reachable_from_2[nr][nc]:
                                    reachable_from_2[nr][nc] = new_d
                                    q.append((nr, nc, new_d))

    # Now check what cells become 1
    print("Changes to 1 (distances from 2s):")
    for r in range(20):
        for c in range(20):
            if demo_in[r][c] == 3 and demo_out[r][c] == 1:
                d = reachable_from_2[r][c]
