from collections import deque

def count_reaching_2s(grid):
    rows = len(grid)
    cols = len(grid[0])

    # For each cell, count how many 2s can reach it
    # A 2 can reach a cell if there's a path of 3s from that 2 to the cell
    reaching_count = [[0]*cols for _ in range(rows)]

    # For each 2, do BFS and increment count for each reachable 3
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 2:
                # BFS from this 2 through 3s only
                q = deque([(r, c)])
                visited = {(r, c)}
                for curr_r, curr_c in q:
                    for nr, nc in [(curr_r-1, curr_c), (curr_r+1, curr_c), 
                                  (curr_r, curr_c-1), (curr_r, curr_c+1)]:
                        if 0 <= nr < rows and 0 <= nc < cols:
                            if grid[nr][nc] == 3 and (nr, nc) not in visited:
                                reaching_count[nr][nc] += 1
                                visited.add((nr, nc))
                                q.append((nr, nc))

    return reaching_count

