                    if 0 <= nr < rows and 0 <= nc < cols:
                        if grid[nr][nc] in [0, 3]:
                            result[nr][nc] = 1
                            changed = True

        # Second pass: if any cell became 1, expand to adjacent cells
        # that were originally 3
        for r in range(rows):
            for c in range(cols):
                if result[r][c] == 1:
                    for dr in [-1, 0, 1]:
