                                queue.append((nr, nc))
                            if grid[nr][nc] == 2:
                                has_2 = True
                                if dist_to_2 == float('inf'):
                                    dist_to_2 = abs(cr - nr) + abs(cc - nc)

    # Check which components have 2s within distance 2
    for comp_r, comp_c in comp_cells:
        if has_2:
